create table if not exists public.offline_packs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, pack_type text not null check (pack_type in ('route','area','business')), name text, west double precision, south double precision, east double precision, north double precision, route_discovery_session_id uuid references public.route_discovery_sessions(id) on delete set null, business_id uuid references public.businesses(id) on delete set null, version bigint not null default 1, status text not null default 'ready' check (status in ('preparing','ready','stale','syncing','failed')), expires_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists offline_packs_user_idx on public.offline_packs(user_id,updated_at desc); create table if not exists public.offline_pack_locations (pack_id uuid not null references public.offline_packs(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, snapshot jsonb not null default '{}'::jsonb, source_version bigint not null default 1, cached_at timestamptz not null default now(), primary key(pack_id,location_id)); create table if not exists public.offline_pack_businesses (pack_id uuid not null references public.offline_packs(id) on delete cascade, business_id uuid not null references public.businesses(id) on delete cascade, snapshot jsonb not null default '{}'::jsonb, source_version bigint not null default 1, cached_at timestamptz not null default now(), primary key(pack_id,business_id)); create table if not exists public.offline_pack_events (id uuid primary key default gen_random_uuid(), pack_id uuid not null references public.offline_packs(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, event_type text not null, payload jsonb not null default '{}'::jsonb, client_event_id text, created_at timestamptz not null default now(), synced_at timestamptz); create index if not exists offline_pack_events_sync_idx on public.offline_pack_events(user_id,synced_at,created_at); alter table public.offline_packs enable row level security; alter table public.offline_pack_locations enable row level security; alter table public.offline_pack_businesses enable row level security; alter table public.offline_pack_events enable row level security; drop policy if exists offline_packs_owner on public.offline_packs; create policy offline_packs_owner on public.offline_packs for all using(auth.uid()=user_id) with check(auth.uid()=user_id); drop policy if exists offline_pack_locations_owner on public.offline_pack_locations; create policy offline_pack_locations_owner on public.offline_pack_locations for all using(exists(select 1 from public.offline_packs p where p.id=pack_id and p.user_id=auth.uid())) with check(exists(select 1 from public.offline_packs p where p.id=pack_id and p.user_id=auth.uid())); drop policy if exists offline_pack_businesses_owner on public.offline_pack_businesses; create policy offline_pack_businesses_owner on public.offline_pack_businesses for all using(exists(select 1 from public.offline_packs p where p.id=pack_id and p.user_id=auth.uid())) with check(exists(select 1 from public.offline_packs p where p.id=pack_id and p.user_id=auth.uid())); drop policy if exists offline_pack_events_owner on public.offline_pack_events; create policy offline_pack_events_owner on public.offline_pack_events for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create or replace function public.create_offline_pack(p_pack_type text,p_name text default null,p_business_id uuid default null,p_route_discovery_session_id uuid default null,p_west double precision default null,p_south double precision default null,p_east double precision default null,p_north double precision default null,p_expires_hours integer default 24) returns public.offline_packs language plpgsql security invoker set search_path=public as $$ declare v_user uuid:=auth.uid(); v_pack public.offline_packs; begin if v_user is null then raise exception 'Authentication required'; end if; insert into public.offline_packs(user_id,pack_type,name,business_id,route_discovery_session_id,west,south,east,north,status,expires_at) values(v_user,p_pack_type,p_name,p_business_id,p_route_discovery_session_id,p_west,p_south,p_east,p_north,'preparing',now()+make_interval(hours=>greatest(1,p_expires_hours))) returning * into v_pack; insert into public.offline_pack_locations(pack_id,location_id,snapshot) select v_pack.id,l.id,jsonb_build_object('id',l.id,'name',l.name,'latitude',l.latitude,'longitude',l.longitude,'category',l.category,'address',l.address,'amenities',l.amenities,'is_verified',l.is_verified,'bathroom_verification_status',l.bathroom_verification_status) from public.locations l where (p_route_discovery_session_id is not null and exists(select 1 from public.route_discovery_locations r where r.session_id=p_route_discovery_session_id and r.location_id=l.id)) or (p_west is not null and l.longitude between p_west and p_east and l.latitude between p_south and p_north); if p_business_id is not null then insert into public.offline_pack_businesses(pack_id,business_id,snapshot) select v_pack.id,b.id,to_jsonb(b) from public.businesses b where b.id=p_business_id on conflict do nothing; end if; update public.offline_packs set status='ready',updated_at=now() where id=v_pack.id returning * into v_pack; return v_pack; end $$; grant execute on function public.create_offline_pack(text,text,uuid,uuid,double precision,double precision,double precision,double precision,integer) to authenticated;
